      "question": "The transfer of genetic information from one bacterium to another through a phage is called:",
      "options": [
        "Transformation",
        "Transduction",
        "Conjugation",
        "Transfection"
      ],
      "correctAnswer": 2,
      "explanation": "Transduction is transfer of bacterial DNA via bacteriophage (virus). When phage infects bacterium, it may mistakenly package bacterial DNA instead of its own; this bacterial DNA is then injected into next host bacterium. Transformation is uptake of naked DNA; conjugation is direct cell-to-cell transfer through pilus.",
