      "question": "The enzyme that joins Okazaki fragments during DNA replication is:",
      "options": [
        "Helicase",
        "Primase",
        "DNA Ligase",
        "Topoisomerase"
      ],
      "correctAnswer": 3,
      "explanation": "DNA ligase joins Okazaki fragments on the lagging strand by forming phosphodiester bonds between the 3'-OH of one fragment and 5'-phosphate of the next, after RNA primers are removed and filled by DNA polymerase I. Helicase unwinds DNA; primase makes RNA primers; topoisomerase relieves supercoiling ahead of replication fork.",
      "id": "2019_q177",
      "year": 2019,
