      "correctAnswer": 3,
      "explanation": "Black arm (angular leaf spot) of cotton is caused by Xanthomonas malvacearum (bacterium). Late blight of potato is caused by Phytophthora infestans (water mold/oomycete, caused Irish famine). Leaf rust of wheat by Puccinia striiformis (fungus). Citrus canker by Xanthomonas citri (bacterium, not virus).",
      "id": "2020_q130",
