      "question": "Exchange of gases between blood and tissues takes place by:",
      "options": [
        "Active transport",
        "Simple diffusion",
        "Facilitated diffusion",
        "Osmosis"
      ],
      "correctAnswer": 2,
      "explanation": "O2 and CO2 exchange between blood and tissues occurs by simple diffusion down concentration gradients. O2 diffuses from blood (high pO2) into tissues (low pO2); CO2 diffuses from tissues (high pCO2) into blood. No energy required. This follows Fick's law: rate of diffusion is proportional to surface area and concentration gradient.",
      "id": "2020_q156",
      "year": 2020,
