      "correctAnswer": 3,
      "explanation": "Crossing over (chiasmata formation) occurs during pachytene of meiosis I prophase. At this stage, homologous chromosomes (bivalents) are synapsed and chromatids of homologous chromosomes exchange segments at corresponding loci. This generates genetic recombination and new allele combinations, increasing genetic diversity.",
