      "correctAnswer": 2,
      "explanation": "Klinefelter syndrome (47,XXY) occurs when males have an extra X chromosome. Features: tall stature, small testes, infertility, gynecomastia, and reduced testosterone. Turner syndrome is 45,X0 (female, short, webbed neck, infertile). Down syndrome is trisomy 21. Edward syndrome is trisomy 18.",
