      "explanation": "C4 plants have Kranz anatomy \u2014 a ring of bundle sheath cells surrounding mesophyll cells. CO2 is first fixed by PEP carboxylase in mesophyll (to OAA/malate), then transported to bundle sheath cells where Calvin cycle occurs. This concentrates CO2 around RuBisCO, minimizing photorespiration. Sugarcane and maize are C4 plants.",
