      "correctAnswer": 3,
      "explanation": "In the fluid mosaic model (Singer and Nicolson, 1972), 'fluid' refers to the lateral mobility of phospholipids and proteins within the bilayer \u2014 they can move sideways at rates of about 1 micrometer/second. 'Mosaic' refers to the varied protein distribution. Temperature, cholesterol content affect membrane fluidity.",
