      "correctAnswer": 1,
      "explanation": "Blackman's law of limiting factors (1905): when a process is governed by multiple factors, the rate is limited by the factor present in the minimum (least optimum) supply. In photosynthesis, factors like CO2 concentration, light intensity, and temperature each can be limiting depending on conditions.",
