      "explanation": "Osmoconformers match their internal osmolarity to the surrounding environment. Most marine invertebrates (starfish, jellyfish, crabs) are osmoconformers. Osmoregulators (fish, mammals, birds) maintain constant internal osmolarity despite external changes, using kidneys and gills. Euryhaline organisms can tolerate wide salinity ranges.",
      "id": "2021_q157",
      "year": 2021,
      "subject": "Zoology"
