      "correctAnswer": 3,
      "explanation": "B and T lymphocytes are components of the adaptive (acquired) immune system. They provide specific immunity and immunological memory. NK (natural killer) cells, macrophages, neutrophils, dendritic cells, and physical barriers (skin, mucus, tears, stomach acid) are components of innate immunity \u2014 non-specific, immediate defense.",
