      "question": "Which blood group is called 'universal donor'?",
      "options": [
        "A",
        "B",
        "AB",
        "O"
      ],
      "correctAnswer": 4,
      "explanation": "Blood group O (O negative more precisely) is the universal donor for red blood cell transfusions because O group lacks A and B antigens on RBCs, preventing antibody reactions. AB is universal recipient, having neither anti-A nor anti-B antibodies. ABO blood groups are governed by multiple alleles (IA, IB, i).",
