      "question": "Which of the following protein is found in hair and nails?",
      "options": [
        "Collagen",
        "Keratin",
        "Myosin",
        "Fibrin"
      ],
      "correctAnswer": 2,
      "explanation": "Keratin is the structural protein of hair, nails, skin, feathers, horns, and hooves. It is a fibrous protein rich in cysteine (forming disulfide bonds that give strength). Hard keratin (nails) has more disulfide bonds than soft keratin (hair). Collagen is in connective tissue; myosin in muscle; fibrin in blood clots.",
