      "correctAnswer": 2,
      "explanation": "To fix 6 CO2 (forming one glucose): Calvin cycle requires 18 ATP and 12 NADPH. The 3 stages are: carbon fixation (6CO2 + 6RuBP -> 12 3-PGA), reduction (12 3-PGA -> 12 G3P using 12 ATP + 12 NADPH), and RuBP regeneration (6 ATP). Total: 18 ATP + 12 NADPH.",
