      "question": "What process occurs during the S phase of cell cycle?",
      "options": [
        "Cell growth only",
        "DNA replication",
        "Nuclear division",
        "Cytokinesis"
      ],
      "correctAnswer": 2,
      "explanation": "S phase (Synthesis phase) of interphase is when DNA replication occurs, resulting in duplication of the entire genome. Each chromosome is duplicated to produce two sister chromatids joined at centromere. S phase is preceded by G1 (growth, protein synthesis) and followed by G2 (further growth, preparation for mitosis).",
